import re


_DURATION_RE = re.compile(
    r"(?:([0-9]+)d)?(?:([0-9]+)h)?(?:([0-9]+)m)?(?:([0-9]+)s)?"
)


def parse_duration(s):
    """Convert a duration string such as '1h30m' to an int number of seconds."""
    if not isinstance(s, str):
        raise ValueError("duration must be a string")

    match = _DURATION_RE.fullmatch(s.strip())
    if match is None or all(part is None for part in match.groups()):
        raise ValueError("invalid duration: {!r}".format(s))

    days, hours, minutes, seconds = (
        int(part) if part is not None else 0 for part in match.groups()
    )
    return days * 86400 + hours * 3600 + minutes * 60 + seconds
